+            "Chat should still provide a response.");
+    }
+
+    private static void AssertPassingScores(EvaluationResult result, double threshold = 3.0)
+    {
+        foreach (var metric in result.Metrics)
+        {
+            if (metric.Value is NumericMetricValue numericValue)
+            {
+                Assert.IsTrue(numericValue.Value >= threshold,
+                    $"Metric '{metric.Key}' scored {numericValue.Value}, expected >= {threshold}.");
+            }
+        }
+    }
+}
