namespace MyApp.Evaluation.Infrastructure;

/// <summary>
/// Base class for evaluation tests. Provides access to the chat client and
/// a configured set of evaluators for measuring response quality.
/// </summary>
public abstract class EvaluationBase
{
    private static readonly AppHostFixture s_fixture = new();

    protected static IChatClient ChatClient { get; private set; } = null!;

    [ClassInitialize(InheritanceBehavior.BeforeEachDerivedClass)]
    public static async Task SetUp(TestContext _)
    {
        await s_fixture.StartAsync();
        ChatClient = s_fixture.App.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup(InheritanceBehavior.BeforeEachDerivedClass)]
    public static async Task TearDown()
    {
        await s_fixture.DisposeAsync();
    }

    /// <summary>
    /// Gets the default set of evaluators for quality assessment.
    /// </summary>
    protected static IReadOnlyList<IEvaluator> GetDefaultEvaluators()
    {
        return
        [
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        ];
    }

    /// <summary>
    /// Sends a prompt to the chat client and returns the response.
    /// </summary>
    protected static async Task<ChatResponse> GetResponseAsync(string prompt)
    {
        return await ChatClient.GetResponseAsync(prompt);
    }

    /// <summary>
    /// Evaluates a conversation turn using the provided evaluators.
    /// </summary>
    protected static async Task<EvaluationResult> EvaluateAsync(
        IReadOnlyList<IEvaluator> evaluators,
        IEnumerable<ChatMessage> messages,
        ChatResponse modelResponse)
    {
        var chatConfig = new ChatConfiguration(ChatClient);
        var composite = new CompositeEvaluator(evaluators);
        return await composite.EvaluateAsync(messages, modelResponse, chatConfig);
    }
}

